      // ── 10. 🔎 Universal Chat Search & Message Finder (1v1 & Group) ─────────
      async searchAndLocateMessage(queryText, allMessages, options) {
        const rawClean = (queryText || "").replace(/^(?:@?friday|fridaay|fryday|fraiday)/gi, "").replace(/^(?:@search|\/search|@find|\/find|search|find)\s*/gi, "").trim();
        let targetKeyword = rawClean;
        const pattern1 = rawClean.match(/(?:kisi\s*ne|kisne)\s+(.+?)\s+(?:ke\s*baare\s*me|ke\s*bare\s*me|ke\s*liye|ko\s*lekar)?\s*(?:bola\s*tha|kaha\s*tha|bheja\s*tha|likha\s*tha|message\s*kiya)/i);
        const pattern2 = rawClean.match(/(?:dhundo|dhundho|check\s*karo|dekho)\s+(?:kisi\s*ne\s+)?(.+?)(?:\s+bola\s*tha|\s+bheja\s*tha|\s+kaha\s*tha)?$/i);
        const pattern3 = rawClean.match(/(?:kisi\s*ne\s+)?(.+?)\s+(?:ke\s*bare\s*me\s*kya\s*bola|ke\s*baare\s*me\s*kya\s*bola|ke\s*bare\s*me|ke\s*baare\s*me)/i);
        if (pattern1 && pattern1[1]) {
          targetKeyword = pattern1[1].trim();
        } else if (pattern2 && pattern2[1]) {
          targetKeyword = pattern2[1].trim();
        } else if (pattern3 && pattern3[1]) {
          targetKeyword = pattern3[1].trim();
        }
        const cleanSearchTerm = targetKeyword.replace(/^(?:kisi\s*ne|kisne|kya|bhai|koi|msg|message|chat\s*me)\s+/gi, "").replace(/\s+(?:ke\s*baare\s*me|ke\s*bare\s*me|bola\s*tha|kaha\s*tha|bheja\s*tha|tha|kya)$/gi, "").trim();
        if (!cleanSearchTerm || cleanSearchTerm.length < 2) {
          return {
            found: false,
            replyText: `\u{1F50D} *Message Search:*
Aapko chat me kya search karna hai? Example: _"friday kisi ne meeting ke bare me bola tha"_ ya _"friday search project"_
_Main poori chat scan karke sender aur time ke sath dhoondh dungi!_`
          };
        }
        const tokens = cleanSearchTerm.toLowerCase().split(/\s+/).filter((t) => t.length > 1);
        const scoredMatches = [];
        for (const m of allMessages) {
          if (m.text.toLowerCase().includes("kisi ne") && m.text.toLowerCase().includes("bola tha")) continue;
          const fullContent = `${m.text} ${m.senderName} ${m.groupName || ""}`.toLowerCase();
          let matchScore = 0;
          if (fullContent.includes(cleanSearchTerm.toLowerCase())) {
            matchScore += 10;
          }
          for (const token of tokens) {
            if (fullContent.includes(token)) {
              matchScore += 3;
            }
          }
          if (matchScore > 0) {
            scoredMatches.push({ msg: m, score: matchScore });
          }
        }
        scoredMatches.sort((a, b) => b.score - a.score);
        if (scoredMatches.length === 0) {
          return {
            found: false,
            replyText: `\u{1F50D} *Search Result:*
Mujhe chat me *"${cleanSearchTerm}"* se match karta hua koi purana message nahi mila. Aap thoda different keyword try kar sakte hain!`
          };
        }
        const best = scoredMatches[0].msg;
        const isGroup = !!options?.isGroup;
        let reply = "";
        if (isGroup) {
          reply = `\u{1F50E} *Haan! Group me yeh message mila:*

\u{1F464} *Sender:* **${best.senderName}**
\u{1F4C5} *Time:* _${best.dateStr}_
\u{1F4AC} *Message:* 
> _"${best.text.slice(0, 350)}"_

\u{1F4A1} *${best.senderName} ne yeh message bheja tha.*`;
        } else {
          reply = `\u{1F50E} *Haanji! Mujhe yeh message mil gaya hai:*

\u{1F464} *Sender:* **${best.senderName}** (+${best.senderPhone})
\u{1F4C5} *Date & Time:* _${best.dateStr}_
\u{1F4AC} *Message Content:* 
> _"${best.text.slice(0, 350)}"_

\u2728 *${best.senderName} ne yeh message bheja tha.*`;
        }
        if (scoredMatches.length > 1) {
          const otherMatches = scoredMatches.slice(1, 3).map(
            (sm) => `\u2022 *${sm.msg.senderName}* [_${sm.msg.dateStr}_]: _"${sm.msg.text.slice(0, 80)}"_`
          );
          reply += `

\u{1F4CC} *Kuch aur related messages bhi mile:*
${otherMatches.join("\n")}`;
        }
        return {
          found: true,
          replyText: reply,
          topMatch: best
        };
      }
