      // ── 1. @tagall / @everyone Engine ──────────────────────────────────────────
      async handleTagAll(sock, groupJid, groupName, rawText, senderName) {
        if (!sock) return { handled: true, replyText: "\u26A0\uFE0F Friday WhatsApp connection error." };
        try {
          const meta = await sock.groupMetadata(groupJid);
          if (!meta || !Array.isArray(meta.participants)) {
            return { handled: true, replyText: "\u26A0\uFE0F Group participants list fetch nahi ho saki." };
          }
          const botJid = sock.user?.id || "";
          const participants = meta.participants.filter((p) => !p.id.includes(botJid.split(":")[0]));
          const mentions = participants.map((p) => p.id);
          const noticeContent = rawText.replace(/^(?:@tagall|@everyone|\/tagall|\/everyone|tag\s*all|everyone)\s*[:=-]?\s*/i, "").trim();
          const announcementMsg = noticeContent || "Zaroori suchna / Dhyan dein sabhi members!";
          const memberTagsList = participants.slice(0, 35).map((p) => `@${p.id.split("@")[0].split(":")[0].replace(/\D/g, "")}`).join(" ");
          const extraCount = participants.length > 35 ? ` ...aur ${participants.length - 35} log` : "";
          const card = `\u{1F4E2} *GROUP ANNOUNCEMENT (@everyone)* \u26A1
\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501
\u{1F465} *Group:* ${groupName}
\u{1F464} *Announced By:* ${senderName}
\u{1F4AC} *Message:*
"${announcementMsg}"
\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501\u2501
\u{1F514} *Attention Members (${participants.length}):*
${memberTagsList}${extraCount}`;
          return {
            handled: true,
            replyText: card,
            mentions
          };
        } catch (err) {
          console.error("[GroupSuperPowers] TagAll error:", err);
          return { handled: true, replyText: `\u26A0\uFE0F Tag All failed: ${err?.message || err}` };
        }
      }
