import crypto5 from "crypto";
function resolveEncryptionKey() {
  const raw = process.env.ENCRYPTION_KEY;
  if (raw && raw.length >= 32) {
    return crypto5.createHash("sha256").update(raw).digest();
  }
  return crypto5.createHash("sha256").update(raw || "friday_default_memory_master_key_2026").digest();
}
var ENCRYPTION_KEY = resolveEncryptionKey();
function encrypt(text) {
  const iv = crypto5.randomBytes(12);
  const cipher = crypto5.createCipheriv("aes-256-gcm", ENCRYPTION_KEY, iv);
  const ciphertext = Buffer.concat([cipher.update(text, "utf8"), cipher.final()]);
  const authTag = cipher.getAuthTag();
  return Buffer.concat([iv, authTag, ciphertext]).toString("base64");
}
function decrypt(payload) {
  try {
    const buf = Buffer.from(payload, "base64");
    const iv = buf.subarray(0, 12);
    const authTag = buf.subarray(12, 28);
    const ciphertext = buf.subarray(28);
    const decipher = crypto5.createDecipheriv("aes-256-gcm", ENCRYPTION_KEY, iv);
    decipher.setAuthTag(authTag);
    return Buffer.concat([decipher.update(ciphertext), decipher.final()]).toString("utf8");
  } catch (e) {
    return "";
  }
}
var historyCollection = () => db.collection("history");
async function saveMessage(sender, text) {
  if (!text || !text.trim()) return;
  try {
    await historyCollection().add({
      sender,
      ciphertext: encrypt(text.trim()),
      created_at: Date.now(),
      createdAtServer: FieldValue.serverTimestamp()
    });
  } catch (err) {
    console.error("[HistoryService] Failed to save message to Firestore:", err);
  }
}
async function getHistory(limit = 50, beforeTimestamp) {
  try {
    const query = beforeTimestamp ? historyCollection().where("created_at", "<", beforeTimestamp).orderBy("created_at", "desc").limit(limit) : historyCollection().orderBy("created_at", "desc").limit(limit);
    const snapshot = await query.get();
    const messages = snapshot.docs.map((doc) => {
      const data = doc.data();
      return {
        id: doc.id,
        sender: data.sender,
        text: decrypt(data.ciphertext),
        timestamp: data.created_at
      };
    });
    return messages.reverse();
  } catch (err) {
    console.error("[HistoryService] Failed to load history from Firestore:", err);
    return [];
  }
}
async function clearHistory() {
  try {
    const snapshot = await historyCollection().limit(500).get();
    if (snapshot.empty) return;
    const batch = db.batch();
    snapshot.docs.forEach((doc) => batch.delete(doc.ref));
    await batch.commit();
    if (snapshot.size === 500) {
      await clearHistory();
    }
  } catch (err) {
    console.error("[HistoryService] Failed to clear history in Firestore:", err);
  }
}

