function detectCms(body, headers) {
  const detected = [];
  const combined = (body + JSON.stringify(headers)).toLowerCase();
  for (const [cms, patterns] of Object.entries(CMS_PATTERNS)) {
    if (patterns.some((p) => combined.includes(p.toLowerCase()))) {
      detected.push(cms);
    }
  }
  return detected;
}
