    const parsed = new URL(targetUrl);
    const baseUrl = `${parsed.protocol}//${parsed.hostname}${parsed.port ? ":" + parsed.port : ""}`;
    const protocol = parsed.protocol === "https:" ? "https" : "http";
    const port = parseInt(parsed.port) || (protocol === "https" ? 443 : 80);
