        findings.push({
          id: "INFO-POWERED-BY",
          severity: "low",
          category: "Information Disclosure",
          title: "X-Powered-By header disclosed",
          description: `X-Powered-By reveals: "${poweredBy}"`,
          evidence: poweredBy,
          remediation: "Remove X-Powered-By header"
        });
