          findings.push({
            id: "COOKIE-SECURE",
            severity: "medium",
            category: "Cookie Security",
            title: "Cookie missing Secure flag",
            description: "Cookie may be sent over HTTP (man-in-the-middle risk)",
            evidence: cookieStr.substring(0, 100),
            remediation: "Add Secure flag to all cookies"
          });
