                severity: "high",
                category: "Directory Listing",
                title: `Directory listing enabled: ${check.path}`,
                description: `Directory listing is enabled at ${check.path} \u2014 file structure exposed`,
                url: fullUrl,
                evidence: `HTTP ${resp.statusCode} \u2014 "Index of" found in response`,
                remediation: "Disable directory listing in webserver config"
