              id: `PATH-${check.path.replace(/[^a-z0-9]/gi, "_").toUpperCase()}`,
              severity: check.severity,
              category: check.category,
              title: check.title,
              description: check.description,
              url: fullUrl,
              evidence: `HTTP ${resp.statusCode}${resp.body.length > 0 ? ` (${resp.body.length} bytes)` : ""}`,
