    const securityScore = Math.max(0, 100 - deductions);
    const grade = securityScore >= 90 ? "A" : securityScore >= 75 ? "B" : securityScore >= 60 ? "C" : securityScore >= 40 ? "D" : "F";
    const scanDurationMs = Date.now() - startTime;
    const totalFindings = findings.filter((f) => f.severity !== "info").length;
    const summary = `\u{1F50D} Nikto scan complete for "${baseUrl}"
\u{1F4CA} Security Score: ${securityScore}/100 (Grade: ${grade})
\u{1F6A8} Critical: ${findingsBySeverity["critical"] || 0}
\u{1F534} High: ${findingsBySeverity["high"] || 0}
\u{1F7E0} Medium: ${findingsBySeverity["medium"] || 0}
\u{1F7E1} Low: ${findingsBySeverity["low"] || 0}
\u2139\uFE0F Info: ${findingsBySeverity["info"] || 0}
\u{1F5A5}\uFE0F Server: ${serverBanner || "Hidden"}
\u{1F4E6} CMS: ${cmsDetected || "Not detected"}
\u{1F522} Requests made: ${totalRequests}
\u23F1\uFE0F Scan time: ${(scanDurationMs / 1e3).toFixed(1)}s`;
