      port,
      protocol,
      serverBanner: serverBanner || void 0,
      poweredBy: poweredBy || void 0,
      findings,
      securityScore,
      grade,
      cmsDetected,
      technologiesDetected,
      allowedMethods,
      totalRequests,
      summary,
      scanDurationMs,
      findingsBySecerity: findingsBySeverity
