    const audioId = req.params.audioId;
    console.log(`[ExotelDiagnostic] \u{1F50A} AUDIO_FETCH Request: Method=${req.method} AudioId=${audioId} Range=${req.headers.range || "none"}`);
    const audio = exotelService.getAudio(audioId);
